        }
    });
    
    function setQuestionValue(qId, val) {

        Confirmit.page.getQuestion(qId).setValue(val);
    }

    function addActive(x) {
        /*a function to classify an item as "active":*/
        if (!x) return false;
        /*start by removing the "active" class on all items:*/
        removeActive(x);
        if (currentFocus >= x.length) currentFocus = 0;
        if (currentFocus < 0) currentFocus = (x.length - 1);
        /*add class "autocomplete-active":*/
        x[currentFocus].classList.add("autocomplete-active");
    }
    function removeActive(x) {
        /*a function to remove the "active" class from all autocomplete items:*/
        for (var i = 0; i < x.length; i++) {
            x[i].classList.remove("autocomplete-active");
        }
    }
    function closeAllLists(elmnt) {
        /*close all autocomplete lists in the document,
        except the one passed as an argument:*/
        var x = document.getElementsByClassName("autocomplete-items");
        for (var i = 0; i < x.length; i++) {
            if (elmnt != x[i] && elmnt != inp) {
                x[i].parentNode.removeChild(x[i]);
            }
        }
    }
    /*execute a function when someone clicks in the document:*/
    document.addEventListener("click", function (e) {
        closeAllLists(e.target);
    });
}


function validateData(){
    var result = Confirmit.page.validate();
    var errors = result.questionValidationResults.length;
    if(errors == 0){
        saveData();
    }
}

function clearData() {
    var responses = Confirmit.page.questions;
    for (var i = 0; i < responses.length; i++) {
        var question = responses[i];
        if(Object.keys(question.formValues).length > 0){
            question.clearValues();
        }
    }
}

function saveData() {

    var url = document.URL;
    var params = Confirmit.page.serverVariables._fields;

    var responses = Confirmit.page.formValues;
    for (var i = 0; i < responses.length; i++) {
        var name = responses[i]["name"];
        var value = responses[i]["value"];
        params[name] = value;
    }

    var xhr = new XMLHttpRequest();
    xhr.open("POST", url, true);
    xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
    xhr.onreadystatechange = function () {
        if (xhr.readyState === 4 && xhr.status === 200) {
            document.getElementById("save-btn").innerText = "Saved!";
            setTimeout(function () {
                document.getElementById("save-btn").innerText = "Save and close";
            }, 2000);
        }
    };
    var queryString = new URLSearchParams(params).toString();
    xhr.send(queryString);
}

