function calcScale5(targetVar, minNum) {
    var scale = 0;
    var count = 0;

    var scores = {
        "1": 0,
        "2": 25,
        "3": 50,
        "4": 75,
        "5": 100
    };

    var codes = f(CurrentForm()).domainValues();

    for (var i = 0; i < codes.length; i++) {
        var code = codes[i];

        for (var value in scores) {
            if (f(CurrentForm()).item(code).any(value)) {
                scale += scores[value];
                count++;
                break;
            }
        }
    }
    if (count >= minNum){
       return targetVar.set(scale / count)
    }


}

function calcScale4(targetVar, minNum) {
    var scale = 0;
    var count = 0;

    var scores = {
        "1": 0,
        "2": 33.33,
        "3": 66.66,
        "4": 100
    };

    var codes = f(CurrentForm()).domainValues();

    for (var i = 0; i < codes.length; i++) {
        var code = codes[i];

        for (var value in scores) {
            if (f(CurrentForm()).item(code).any(value)) {
                scale += scores[value];
                count++;
                //break;
            }
        }
    }
    if (count >= minNum){
       return targetVar.set(scale / count)
    }

}

