if (f(CurrentForm()).toBoolean() || f(CurrentForm()).getNoResponseValue()!= null)
{
const qn_Location_RUR_BG_PCODE = "Location_RUR_BG_PCODE";
const qn_state = "s_state_RUR_BG_PCODE";
const qn_finalPcode = "finalPostcode_RUR_BG_PCODE";
const qn_pcodeList = "pcode_list_RUR_BG_PCODE"
// Clears all Location_RUR_BG_PCODE-related fields
function clearLocation_RUR_BG_PCODEFields() {
    const Location_RUR_BG_PCODEFields = [
        "finalPostcode_RUR_BG_PCODE",
        "finalSuburb_RUR_BG_PCODE",
        "finalState_RUR_BG_PCODE",
        "finalLGA_pcprim_RUR_BG_PCODE",
        "finalLGA_locprim_RUR_BG_PCODE",
        "finalCombined_RUR_BG_PCODE",
        "finalMarket_RUR_BG_PCODE",
        "finalMarket_name_RUR_BG_PCODE",
        "finalRemoteness_RUR_BG_PCODE",
        "finalSEIFA_irsd_RUR_BG_PCODE"
    ];
    Location_RUR_BG_PCODEFields.forEach(field => f(field).set(""));
}

// error message for invalid postcode
var errmsg;
function setError() {
    clearLocation_RUR_BG_PCODEFields();
    RaiseError();
    ClearErrorMessage();
    ClearQuestionErrorMessage();
    SetQuestionErrorMessage(LangIDs.en_au, errmsg);
}

function validatePcode(pcode, state, array) {
    var postcode = String(pcode).padStart(4, '0');
    var getStates = [...new Set(array.map(([_, state]) => state))];
    var getPcodes = [...new Set(array.map(([pcode, _]) => pcode))];
    if (getStates.includes(state)) {
        if(array.some(([pc, st]) => pc === postcode && st === state)) {
            return postcode;
        } else {
            errmsg = "Please enter a postcode within " + state + ".";
        }   
    } else {
        if (getPcodes.includes(postcode)) {
            return postcode
        } else {
            errmsg = "Please enter a valid postcode to proceed.";
        }
    }
    return null;
}

// if not DK/REF, validate postcode
const noResponseValue = f(qn_Location_RUR_BG_PCODE).getNoResponseValue();
if (noResponseValue == null) { // validate entry
    const Location_RUR_BG_PCODEResponse = f(qn_Location_RUR_BG_PCODE).toString().slice(0,4);
    if (Number(Location_RUR_BG_PCODEResponse) > 0) {
        f(qn_finalPcode).set(validatePcode(Location_RUR_BG_PCODEResponse, f(qn_state).get(), JSON.parse(f(qn_pcodeList))));
    }
    if (f(qn_finalPcode).toBoolean()) {
        if (!Location_RUR_BG_PCODEResponse.includes(f(qn_finalPcode).get())) {
            setError();
        }
    } else { // finalpcode is empty - no match
        setError();
    }
} else {
    clearLocation_RUR_BG_PCODEFields();
}
}
f('Location_RUR_BG_PCODE_NA').set(null);
if (!f('Location_RUR_BG_PCODE').toBoolean())
{
    if (f('Location_RUR_BG_PCODE').getNoResponseValue()=='dk') {
        f('Location_RUR_BG_PCODE_NA').set('2');
    }
    if (f('Location_RUR_BG_PCODE').getNoResponseValue()=='ref') {
        f('Location_RUR_BG_PCODE_NA').set('3');
    }
    if (f('Location_RUR_BG_PCODE').getNoResponseValue()== null) {
        f('Location_RUR_BG_PCODE_NA').set('1000');
    }
}

